//go:build ignore

package main

import (
	"fmt"
	"io"

	"github.com/RyuaNerin/go-krypto/internal/generators"
)

const (
	fileName   = "generic_compress.go"
	fileHeader = `
// Code generated by generate_compress.go. DO NOT EDIT.

package lsh256

import (
	"encoding/binary"
	"math/bits"
)
`
)

func main() {
	generators.WriteBody(
		fileName,
		fileHeader, "",
		func(w io.Writer) {
			fmt.Fprintln(
				w, `
func (ctx *lsh256ContextData) compress(b *block) {
	var even, odd [16]uint32
	var l0, l1, l2, l3, l4, l5, l6, l7 uint32
	var r0, r1, r2, r3, r4, r5, r6, r7 uint32
	var temp uint32

	_ = b[BlockSize-1]`,
			)
			compress(w)
			fmt.Fprintln(w, `}`)
		},
	)
}

const (
	ROT_EVEN_ALPHA = 29
	ROT_EVEN_BETA  = 1
	ROT_ODD_ALPHA  = 5
	ROT_ODD_BETA   = 17

	NUM_STEPS = 26
)

var g_gamma256 = [8]int{0, 8, 16, 24, 24, 16, 8, 0}

func add_blk(w io.Writer, msgVarL, msgVarR [8]string) {
	fmt.Fprintln(w, " {")
	defer fmt.Fprintln(w, "}")

	for i := range 8 {
		fmt.Fprintf(w, "l%d = ctx.cvL[%d] ^ %s\n", i, i, msgVarL[i])
		fmt.Fprintf(w, "r%d = ctx.cvR[%d] ^ %s\n", i, i, msgVarR[i])
	}
}

func rotate_blk___xor_with_const(w io.Writer, constOff, alpha int) {
	fmt.Fprintln(w, " {")
	defer fmt.Fprintln(w, "}")

	for i := range 8 {
		fmt.Fprintf(w, "l%d = bits.RotateLeft32(l%d+r%d, %d) ^ stepConstants[%d]\n", i, i, i, alpha, constOff+i)
	}
}

func rotate_blk(w io.Writer, rot_beta int) {
	fmt.Fprintln(w, " {")
	defer fmt.Fprintln(w, "}")

	for i := range 8 {
		fmt.Fprintf(w, "r%d = bits.RotateLeft32(r%d+l%d, %d)\n", i, i, i, rot_beta)
	}
}

func add_blk___rotate_msg_gamma(w io.Writer) {
	fmt.Fprintln(w, " {")
	defer fmt.Fprintln(w, "}")

	for i := range 8 {
		storeCV(w, i, fmt.Sprintf("l%d + r%d", i, i))
		if g_gamma256[i] == 0 {
			storeCV(w, i+8, fmt.Sprintf("r%d", i))
		} else {
			storeCV(w, i+8, fmt.Sprintf("bits.RotateLeft32(r%d, %d)", i, g_gamma256[i]))
		}
	}
}

func mix(w io.Writer, cl_l, cv_r [8]string, const_v, rot_alpha, rot_beta int) {
	fmt.Fprintln(w, " {")
	defer fmt.Fprintln(w, "}")

	fmt.Fprintln(w, "// add_blk(cv_l, cv_r)")
	add_blk(w, cl_l, cv_r)

	fmt.Fprintln(w, "// rotate_blk(cv_l, rot_alpha);")
	fmt.Fprintln(w, "// xor_with_const(cv_l, const_v);")
	rotate_blk___xor_with_const(w, const_v, rot_alpha)

	fmt.Fprintln(w, "// add_blk(cv_l, cv_r)")

	fmt.Fprintln(w, "// rotate_blk(cv_r, rot_beta);")
	rotate_blk(w, rot_beta)

	fmt.Fprintln(w, "// add_blk(cv_l, cv_r)")
	fmt.Fprintln(w, "// rotate_msg_gamma(cv_r)")
	add_blk___rotate_msg_gamma(w)
}

func word_perm(w io.Writer) {
	fmt.Fprintln(w, " {")
	defer fmt.Fprintln(w, "}")

	swap := func(dst int, src int) {
		fmt.Fprintf(w, "%s = %s\n", cv_rl(dst), cv_rl(src))
	}
	fmt.Fprintf(w, "temp = %s\n", cv_rl(cv_l+0))
	swap(cv_l+0, cv_l+6)
	swap(cv_l+6, cv_r+6)
	swap(cv_r+6, cv_r+2)
	swap(cv_r+2, cv_l+1)
	swap(cv_l+1, cv_l+4)
	swap(cv_l+4, cv_r+4)
	swap(cv_r+4, cv_r+0)
	swap(cv_r+0, cv_l+2)
	swap(cv_l+2, cv_l+5)
	swap(cv_l+5, cv_r+7)
	swap(cv_r+7, cv_r+1)
	fmt.Fprintf(w, "%s = temp\n", cv_rl(cv_r+1))
	fmt.Fprintf(w, "temp = %s\n", cv_rl(cv_l+3))
	swap(cv_l+3, cv_l+7)
	swap(cv_l+7, cv_r+5)
	swap(cv_r+5, cv_r+3)
	fmt.Fprintf(w, "%s = temp\n", cv_rl(cv_r+3))
}

const (
	cv_l = 0
	cv_r = 8
)

func cv_rl(idx int) string {
	if idx < cv_r {
		return fmt.Sprintf("ctx.cvL[%d]", idx)
	}
	return fmt.Sprintf("ctx.cvR[%d]", idx-8)
}

func storeCV(w io.Writer, idx int, expr string) {
	fmt.Fprintf(w, "%s = %s\n", cv_rl(idx), expr)
}

func msg_exp(w io.Writer, dst, src string) {
	fmt.Fprintln(w, " {")
	defer fmt.Fprintln(w, "}")

	idxes := [4][4]int{
		{0, 3, 1, 2},
		{4, 7, 6, 5},
		{8, 11, 9, 10},
		{12, 15, 14, 13},
	}
	for _, g := range idxes {
		a, b, c, d := g[0], g[1], g[2], g[3]
		fmt.Fprintf(w, "temp = %s[%d]\n", dst, a)
		fmt.Fprintf(w, "%s[%d] = %s[%d] + %s[%d]\n", dst, a, src, a, dst, b)
		fmt.Fprintf(w, "%s[%d] = %s[%d] + %s[%d]\n", dst, b, src, b, dst, c)
		fmt.Fprintf(w, "%s[%d] = %s[%d] + %s[%d]\n", dst, c, src, c, dst, d)
		fmt.Fprintf(w, "%s[%d] = %s[%d] + temp\n", dst, d, src, d)
	}
}

func compress(w io.Writer) {
	fmt.Fprintln(w, "// load_msg_blk(i_state, pdMsgBlk);")
	fmt.Fprintln(w, "{")
	{
		for i := range 16 {
			off := i * 4
			fmt.Fprintf(w, "even[%d] = binary.LittleEndian.Uint32(b[%d:%d])\n", i, off, off+4)
		}
		for i := range 16 {
			off := 64 + i*4
			fmt.Fprintf(w, "odd[%d] = binary.LittleEndian.Uint32(b[%d:%d])\n", i, off, off+4)
		}
	}
	fmt.Fprintln(w, "}")
	fmt.Fprintln(w)

	msg_add___load_sc := func(arr string) (l, r [8]string) {
		for i := range 8 {
			l[i] = fmt.Sprintf("%s[%d]", arr, i)
			r[i] = fmt.Sprintf("%s[%d]", arr, i+8)
		}
		return
	}

	{
		fmt.Fprintln(w, "// msg_add_even(cv_l, cv_r, i_state);")
		fmt.Fprintln(w, "// load_sc(&const_v, 0);")
		l, r := msg_add___load_sc("even")

		fmt.Fprintln(w, "// mix(cv_l, cv_r, const_v, ROT_EVEN_ALPHA, ROT_EVEN_BETA);")
		mix(w, l, r, 0, ROT_EVEN_ALPHA, ROT_EVEN_BETA)

		fmt.Fprintln(w, "// word_perm(cv_l, cv_r);")
		word_perm(w)
	}
	fmt.Fprintln(w)

	{
		fmt.Fprintln(w, "// msg_add_odd(cv_l, cv_r, i_state);")
		fmt.Fprintln(w, "// load_sc(&const_v, 8);")
		l, r := msg_add___load_sc("odd")

		fmt.Fprintln(w, "// mix(cv_l, cv_r, const_v, ROT_ODD_ALPHA, ROT_ODD_BETA);")
		mix(w, l, r, 8, ROT_ODD_ALPHA, ROT_ODD_BETA)

		fmt.Fprintln(w, "// word_perm(cv_l, cv_r);")
		word_perm(w)
	}
	fmt.Fprintln(w)

	for i := 1; i < NUM_STEPS/2; i++ {
		fmt.Fprintf(w, "// i = %d\n", i)

		{
			fmt.Fprintln(w, "// msg_exp_even(i_state)")
			msg_exp(w, "even", "odd")

			fmt.Fprintln(w, "// msg_add_even(cv_l, cv_r, i_state);")
			fmt.Fprintln(w, "// load_sc(&const_v, 16 * i);")
			l, r := msg_add___load_sc("even")

			fmt.Fprintln(w, "// mix(cv_l, cv_r, const_v, ROT_EVEN_ALPHA, ROT_EVEN_BETA);")
			mix(w, l, r, 16*i, ROT_EVEN_ALPHA, ROT_EVEN_BETA)

			fmt.Fprintln(w, "// word_perm(cv_l, cv_r);")
			word_perm(w)
		}
		fmt.Fprintln(w)

		{
			fmt.Fprintln(w, "// msg_exp_odd(i_state);")
			msg_exp(w, "odd", "even")

			fmt.Fprintln(w, "// msg_add_odd(cv_l, cv_r, i_state);")
			fmt.Fprintln(w, "// load_sc(&const_v, 16 * i + 8);")
			l, r := msg_add___load_sc("odd")

			fmt.Fprintln(w, "// mix(cv_l, cv_r, const_v, ROT_ODD_ALPHA, ROT_ODD_BETA);")
			mix(w, l, r, 16*i+8, ROT_ODD_ALPHA, ROT_ODD_BETA)

			fmt.Fprintln(w, "// word_perm(cv_l, cv_r);")
			word_perm(w)
		}
		fmt.Fprintln(w)
	}

	fmt.Fprintln(w, "// msg_exp_even(i_state);")
	msg_exp(w, "even", "odd")

	fmt.Fprintln(w, "// msg_add_even(cv_l, cv_r, i_state);")
	{
		for i := range 8 {
			fmt.Fprintf(w, "ctx.cvL[%d] ^= even[%d]\n", i, i)
		}
		for i := range 8 {
			fmt.Fprintf(w, "ctx.cvR[%d] ^= even[%d]\n", i, i+8)
		}
	}
}
